import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());int totalOnes = 0;for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());if (a[i] == 1) totalOnes++;}int maxGain = -1;int currentGain = 0;boolean allOnes = true;for (int i = 0; i < n; i++) {if (a[i] == 0) {allOnes = false;currentGain++;} else {currentGain--;}if (currentGain < 0) currentGain = 0;if (currentGain > maxGain) maxGain = currentGain;}if (allOnes) {System.out.println(n - 1);} else {System.out.println(totalOnes + maxGain);}}}